        {
            var shipments = await db.Shipments
                .OrderByDescending(s => s.CreatedAt)
                .Select(s => new ShipmentDto
                {
                    Id = s.Id,
                    TrackingNumber = s.TrackingNumber,
                    Origin = s.Origin,
                    Destination = s.Destination,
                    Status = s.Status,
                    CreatedAt = s.CreatedAt,
                    EstimatedDelivery = s.EstimatedDelivery,
                    ActualDelivery = s.ActualDelivery,
                    RecipientName = s.RecipientName,
                    SenderName = s.SenderName,
                    WeightKg = s.WeightKg,
                    Notes = s.Notes
                })
                .ToListAsync();
            return Results.Ok(shipments);
        });

        group.MapGet("/{id:int}", async (int id, ApplicationDbContext db) =>
        {
            var shipment = await db.Shipments.FindAsync(id);
            if (shipment is null) return Results.NotFound();
            return Results.Ok(new ShipmentDto
            {
                Id = shipment.Id,
                TrackingNumber = shipment.TrackingNumber,
                Origin = shipment.Origin,
                Destination = shipment.Destination,
                Status = shipment.Status,
                CreatedAt = shipment.CreatedAt,
                EstimatedDelivery = shipment.EstimatedDelivery,
                ActualDelivery = shipment.ActualDelivery,
                RecipientName = shipment.RecipientName,
                SenderName = shipment.SenderName,
                WeightKg = shipment.WeightKg,
                Notes = shipment.Notes
            });
        });

        group.MapPost("/", async (ShipmentDto dto, ApplicationDbContext db) =>
        {
            var shipment = new Shipment
            {
                TrackingNumber = $"TRK-{DateTime.UtcNow:yyyyMMdd}-{Random.Shared.Next(10000, 99999)}",
                Origin = dto.Origin,
                Destination = dto.Destination,
                Status = ShipmentStatus.Pending,
                CreatedAt = DateTime.UtcNow,
                EstimatedDelivery = dto.EstimatedDelivery,
                RecipientName = dto.RecipientName,
                SenderName = dto.SenderName,
                WeightKg = dto.WeightKg,
                Notes = dto.Notes
            };
            db.Shipments.Add(shipment);
            await db.SaveChangesAsync();

            db.ShipmentEvents.Add(new ShipmentEvent
            {
                ShipmentId = shipment.Id,
                Timestamp = DateTime.UtcNow,
                Description = "Shipment created",
                Location = shipment.Origin
            });
            await db.SaveChangesAsync();

            return Results.Created($"/api/shipments/{shipment.Id}", new ShipmentDto
            {
                Id = shipment.Id,
                TrackingNumber = shipment.TrackingNumber,
                Origin = shipment.Origin,
                Destination = shipment.Destination,
                Status = shipment.Status,
                CreatedAt = shipment.CreatedAt,
                EstimatedDelivery = shipment.EstimatedDelivery,
                RecipientName = shipment.RecipientName,
                SenderName = shipment.SenderName,
                WeightKg = shipment.WeightKg,
                Notes = shipment.Notes
            });
        });

        group.MapPut("/{id:int}/status", async (int id, ShipmentUpdateDto update, ApplicationDbContext db) =>
        {
            var shipment = await db.Shipments.FindAsync(id);
            if (shipment is null) return Results.NotFound();

            shipment.Status = update.Status;
            if (update.Notes is not null) shipment.Notes = update.Notes;
            if (update.EstimatedDelivery.HasValue) shipment.EstimatedDelivery = update.EstimatedDelivery;
            if (update.Status == ShipmentStatus.Delivered) shipment.ActualDelivery = DateTime.UtcNow;

