                Status = ShipmentStatus.Delivered,
                CreatedAt = DateTime.UtcNow.AddDays(-7),
                EstimatedDelivery = DateTime.UtcNow.AddDays(-2),
                ActualDelivery = DateTime.UtcNow.AddDays(-2),
                RecipientName = "Carlos Rivera",
                SenderName = "LatAm Logistics",
                WeightKg = 25.0
            },
            new()
            {
                TrackingNumber = "TRK-20260605-10005",
                Origin = "Shanghai, China",
                Destination = "San Francisco, USA",
                Status = ShipmentStatus.Pending,
                CreatedAt = DateTime.UtcNow,
                EstimatedDelivery = DateTime.UtcNow.AddDays(10),
                RecipientName = "Alex Chen",
                SenderName = "Pacific Trade Co",
                WeightKg = 45.0
            }
        };

        db.Shipments.AddRange(shipments);
        await db.SaveChangesAsync();

        var events = new List<ShipmentEvent>
        {
            new() { ShipmentId = 1, Timestamp = DateTime.UtcNow.AddDays(-3), Description = "Shipment created", Location = "New York, USA" },
            new() { ShipmentId = 1, Timestamp = DateTime.UtcNow.AddDays(-2), Description = "Picked up by carrier", Location = "New York, USA" },
            new() { ShipmentId = 1, Timestamp = DateTime.UtcNow.AddDays(-1), Description = "In transit - departed hub", Location = "Newark, USA" },
            new() { ShipmentId = 2, Timestamp = DateTime.UtcNow.AddDays(-1), Description = "Shipment created", Location = "Tokyo, Japan" },
            new() { ShipmentId = 2, Timestamp = DateTime.UtcNow.AddHours(-6), Description = "Picked up by carrier", Location = "Tokyo, Japan" },
            new() { ShipmentId = 3, Timestamp = DateTime.UtcNow.AddDays(-5), Description = "Shipment created", Location = "Berlin, Germany" },
