            new() { ShipmentId = 4, Timestamp = DateTime.UtcNow.AddDays(-2), Description = "Delivered", Location = "Mexico City, Mexico" },
            new() { ShipmentId = 5, Timestamp = DateTime.UtcNow, Description = "Shipment created - awaiting pickup", Location = "Shanghai, China" },
        };

        db.ShipmentEvents.AddRange(events);
        await db.SaveChangesAsync();
    }
}

