+@page "/track"
+@page "/"
+@using ShipmentTracker.Shared
+@rendermode InteractiveAuto
+@inject HttpClient Http
+
+<PageTitle>Track Your Shipment</PageTitle>
+
+<div class="container">
+    <div class="row justify-content-center mt-4">
+        <div class="col-md-8">
+            <h3>🔍 Track Your Shipment</h3>
+            <p class="text-muted">Enter your tracking number to check shipment status and estimated delivery.</p>
+
+            <div class="input-group mb-4">
+                <input type="text" class="form-control form-control-lg" placeholder="Enter tracking number (e.g., TRK-20260601-10001)"
+                       @bind="trackingNumber" @onkeypress="HandleKeyPress" />
+                <button class="btn btn-primary btn-lg" @onclick="TrackShipment" disabled="@isLoading">
+                    @if (isLoading)
+                    {
+                        <span class="spinner-border spinner-border-sm me-1"></span>
+                    }
+                    Track
+                </button>
+            </div>
+
+            @if (errorMessage is not null)
+            {
+                <div class="alert alert-warning">@errorMessage</div>
+            }
+
+            @if (result is not null)
+            {
+                <div class="card">
+                    <div class="card-header d-flex justify-content-between align-items-center">
+                        <strong>@result.TrackingNumber</strong>
+                        <span class="badge @GetStatusBadgeClass(result.Status) fs-6">@result.Status</span>
+                    </div>
+                    <div class="card-body">
+                        <div class="row mb-3">
+                            <div class="col-md-6">
+                                <p><strong>From:</strong> @result.Origin</p>
+                                <p><strong>To:</strong> @result.Destination</p>
+                                <p><strong>Recipient:</strong> @result.RecipientName</p>
+                            </div>
+                            <div class="col-md-6">
+                                @if (result.EstimatedDelivery.HasValue)
+                                {
+                                    <p><strong>Estimated Delivery:</strong>
+                                        <span class="text-primary fw-bold">
+                                            @result.EstimatedDelivery.Value.ToString("dddd, MMM dd, yyyy")
+                                        </span>
+                                    </p>
+                                }
+                                @if (result.ActualDelivery.HasValue)
+                                {
+                                    <p><strong>Delivered On:</strong>
+                                        <span class="text-success fw-bold">
+                                            @result.ActualDelivery.Value.ToString("dddd, MMM dd, yyyy")
+                                        </span>
+                                    </p>
+                                }
+                            </div>
+                        </div>
+
+                        @if (result.Events.Any())
+                        {
+                            <h6>Tracking History</h6>
+                            <div class="list-group">
+                                @foreach (var evt in result.Events)
+                                {
+                                    <div class="list-group-item">
+                                        <div class="d-flex justify-content-between">
+                                            <strong>@evt.Description</strong>
+                                            <small class="text-muted">@evt.Timestamp.ToString("MMM dd, yyyy HH:mm") UTC</small>
+                                        </div>
+                                        <small class="text-muted">📍 @evt.Location</small>
+                                    </div>
+                                }
+                            </div>
+                        }
+                    </div>
+                </div>
+            }
+
+            <div class="mt-4">
+                <h6>Sample Tracking Numbers (for demo):</h6>
+                <div class="d-flex flex-wrap gap-2">
+                    @foreach (var sample in sampleNumbers)
+                    {
+                        <button class="btn btn-outline-secondary btn-sm" @onclick="() => QuickTrack(sample)">
+                            @sample
+                        </button>
+                    }
+                </div>
+            </div>
+        </div>
+    </div>
+</div>
+
+@code {
+    private string trackingNumber = "";
+    private TrackingResult? result;
+    private string? errorMessage;
+    private bool isLoading;
+
+    private readonly string[] sampleNumbers =
+    [
+        "TRK-20260601-10001",
+        "TRK-20260602-10002",
+        "TRK-20260603-10003",
+        "TRK-20260604-10004",
+        "TRK-20260605-10005"
+    ];
+
+    private async Task HandleKeyPress(KeyboardEventArgs e)
+    {
+        if (e.Key == "Enter")
+            await TrackShipment();
+    }
+
+    private async Task TrackShipment()
+    {
+        if (string.IsNullOrWhiteSpace(trackingNumber)) return;
+
+        isLoading = true;
+        errorMessage = null;
+        result = null;
+
+        try
+        {
+            var response = await Http.GetAsync($"/api/track/{trackingNumber.Trim()}");
+            if (response.IsSuccessStatusCode)
+            {
+                result = await response.Content.ReadFromJsonAsync<TrackingResult>();
+            }
+            else
+            {
+                errorMessage = "Shipment not found. Please check your tracking number and try again.";
+            }
+        }
+        catch
+        {
+            errorMessage = "Unable to retrieve tracking information. Please try again later.";
+        }
+        finally
+        {
+            isLoading = false;
+        }
+    }
+
+    private async Task QuickTrack(string number)
+    {
+        trackingNumber = number;
+        await TrackShipment();
+    }
+
+    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
+    {
+        ShipmentStatus.Pending => "bg-secondary",
+        ShipmentStatus.PickedUp => "bg-info",
+        ShipmentStatus.InTransit => "bg-primary",
+        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
+        ShipmentStatus.Delivered => "bg-success",
+        ShipmentStatus.Cancelled => "bg-danger",
+        _ => "bg-secondary"
+    };
+}
+

